/** Represents a change in a Journal's status, sent over the events streaming api. */
export const JournalStatusEventV2Schema = Z.object({
  /** Timestamp of event */
  at: Z.iso.datetime({ offset: true }),
  /** If journal submitted in batch (that is, idempotency_key_type is batch), this is the error message of the batch journal execution. */
  batch_error_message: Z.string().optional(),
  /** The description of the journal event when submitted */
  description: Z.string().optional(),
  entry_type: JournalEntryTypeSchema,
  /** lexically sortable, monotonically increasing character array */
  event_id: Z.string(),
  /** The idempotency key of the journal event */
  idempotency_key: Z.string().optional(),
  /** The type of idempotency key */
  idempotency_key_type: Z.enum(["single", "batch"]).optional(),
  /** The UUID of the related Journal */
  journal_id: Z.string(),
  status_from: JournalStatusFromSchema,
  status_to: JournalStatusSchema,
});
export type JournalStatusEventV2 = Z.output<typeof JournalStatusEventV2Schema>;

/** Response to a successful request for a list of APR tiers. */
